47	const DEFAULT_CONFIG: CertificateDetectionConfig = {
48	  enableTelemetry: true,
49	  scanTimeoutMs: 10000,
50	  excludedExtensions: ['.pem', '.cer'],
51	  validCertExtensions: ['.crt', '.cert', '.key'],
52	  certDirectories: {
53	    system: ['/etc/containers/certs.d'],
54	    user: ['$HOME/.config/containers/certs.d'],
55	  },
56	  followSymlinks: false,
57	};
